function gossipRound(self, clusterView) {
  // pick a small, random subset of known peers
  const peers = pickRandomPeers(clusterView.knownNodes, count = 2);

  for (const peer of peers) {
    const myDigest = self.buildDigest();       // what I currently believe
    const theirDigest = sendDigest(peer, myDigest);

    // merge whichever facts are newer, by version or timestamp
    self.merge(theirDigest);
    sendMerged(peer, self.buildDigest());
  }

  // repeat again next tick, usually about one second later
}

